package com.badrulamin.University_Management.entity;  import com.fasterxml.jackson.annotation.JsonProperty; import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp;  import java.time.LocalDate; import java.time.LocalDateTime;  @Entity @Table(name = "admission_campaign") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class AdmissionCampaign {      @Id     @GeneratedValue(strategy = GenerationType.IDENTITY)     private Long id;      @Column(nullable = false)     private String name;      @Column(length = 50)     private String type;      @Column(length = 500)     private String description;      private Double budget;      private Double spent;      @Column(nullable = false)     private LocalDate startDate;      @Column(nullable = false)     private LocalDate endDate;      @Column(nullable = false)     private String status;      @Column(length = 1000)     private String targetAudience;      @Column(length = 500)     private String channels;      private Integer applicationsGenerated;      private Integer enrollmentsConverted;      @Column(length = 2000)     private String notes;      @ManyToOne(fetch = FetchType.EAGER)     @JoinColumn(name = "session_id")     private AcademicSession session;      @Column(updatable = false)     @CreationTimestamp     private LocalDateTime createdAt;      @UpdateTimestamp     private LocalDateTime updatedAt;      @JsonProperty("sessionId")     @com.fasterxml.jackson.annotation.JsonIgnore     public Long getSessionId() {         return session != null ? session.getId() : null;     }      @JsonProperty("sessionId")     public void setSessionId(Long sessionId) {         if (sessionId != null) {             AcademicSession s = new AcademicSession();             s.setId(sessionId);             this.session = s;         }     } }